// Verbatim port of obs_broadcast.html's inline scripts wrapped for the SPA —
// regenerated by scripts/wrap_obs_js.py; edit the generator, not this file.
import { exposeGlobals, unexposeGlobals } from '../../../lib/legacy.js';
import { toast } from '../../../ui/toast.js';

export function init(ctx, d, G) {
  let _dead = false;
  const OBS_SCROLL_KEY = 'obsCfgScroll';
  // The old page posted a form and reloaded; here a reload is a re-mount,
  // and the scroll position rides sessionStorage across it like before.
  function _obsReload() {
    try { sessionStorage.setItem(OBS_SCROLL_KEY, String(window.scrollY)); } catch (e) {}
    ctx.reload();
  }
  // The old form+redirect endpoints (art upload/clear, "back to the shared
  // look"): multipart POST, toast the {ok, message} answer, re-mount.
  async function _obsSubmitForm(form, submitter) {
    if (!form) return;
    const path = form.getAttribute('action');
    let res, body;
    try {
      res = await fetch(path, { method: 'POST', body: new FormData(form, submitter || undefined) });
      body = await res.json().catch(() => ({}));
    } catch (e) { toast.error('Could not reach ScenePlay.'); return; }
    if (!res.ok || (body && body.ok === false)) { toast.error((body && (body.error || body.message)) || ('HTTP ' + res.status)); return; }
    if (body && body.message) toast.success(body.message);
    _obsReload();
  }
  const OBS_STATE_URL   = "/ttrpg/obs/api/state";
  const OBS_SWITCH_URL  = "/ttrpg/obs/api/switch";
  const OBS_REFRESH_URL = "/ttrpg/obs/api/refresh";
  const OBS_NEXT_URL    = "/ttrpg/obs/api/next";
  const OBS_GROUP_URL   = "/ttrpg/obs/api/group";
  const OBS_BUILD_URL   = "/ttrpg/obs/api/build-party";
  // Built with a placeholder so the kind is substituted client-side rather than
  // concatenated onto a hand-written path.
  const OBS_OUTPUT_URL  = "/ttrpg/obs/api/output/__kind__";
  const OBS_REORDER_URL = "/ttrpg/obs/api/reorder";
  const OBS_CARDOVR_URL = "/ttrpg/obs/api/card-override";
  const OBS_MAPMODE_URL = "/ttrpg/obs/api/map-mode";
  const OBS_MAPRELOAD_URL = "/ttrpg/obs/api/map-reload";
  const OBS_RELOADALL_URL = "/ttrpg/obs/api/reload-sources";
  const OBS_MAPSCENE_URL = "/ttrpg/obs/api/map-scene";
  const OBS_ONSTREAM_URL = "/ttrpg/obs/api/on-stream";

  // Never rejects. A rejected promise here was a SILENT no-op in every caller
  // that had no .catch — the button looked dead and said nothing, which is
  // indistinguishable from a broken button. Failures come back through the same
  // {ok:false, d:{error}} shape every caller already checks, so one fix covers
  // all of them. A non-JSON body (a login redirect, an HTML error page) lands
  // here too, which is what a session that expired behind an open tab looks
  // like.
  function _obsPost(url, body) {
    return fetch(url, {method: 'POST', headers: {'Content-Type': 'application/json'},
                       body: JSON.stringify(body || {})})
      .then(r => r.json()
        .then(d => ({ok: r.ok, d}))
        .catch(() => ({ok: false, d: {ok: false, error:
          'ScenePlay returned an unreadable reply (HTTP ' + r.status +
          '). If you have been logged out, reload the page.'}})))
      .catch(() => ({ok: false, d: {ok: false, error:
        'Could not reach ScenePlay. Is the server still running?'}}));
  }

  function obsSwitchScene(btn) {
    const scene = btn.dataset.scene;
    _obsPost(OBS_SWITCH_URL, {scene})
      .then(({ok, d}) => {
        if (!ok || !d.ok) {
          _obsShowBuildReport({error: (d && d.error) ||
                                      ('Could not switch to "' + scene + '".')});
          return;
        }
        _obsApply({current_scene: d.current_scene});
      })
      // Without this a failed request was a SILENT no-op — the button looked
      // dead and said nothing, which is indistinguishable from a broken button.
      .catch(() => {
        _obsShowBuildReport({error: 'Could not reach ScenePlay to switch to "' +
                                    scene + '". Reload the page and try again.'});
      });
  }

  function obsStep(direction) {
    _obsPost(OBS_NEXT_URL, {direction})
      .then(({ok, d}) => {
        if (!ok || !d.ok) { alert(d.error || 'Could not step the rotation.'); return; }
        _obsApply({current_scene: d.current_scene});
      });
  }

  function obsJump(position) {
    _obsPost(OBS_NEXT_URL, {position})
      .then(({ok, d}) => {
        if (!ok || !d.ok) { alert(d.error || 'Could not switch.'); return; }
        _obsApply({current_scene: d.current_scene});
      });
  }

  function obsGroup() {
    _obsPost(OBS_GROUP_URL, {})
      .then(({ok, d}) => {
        if (!ok || !d.ok) { alert(d.error || 'Could not switch to the group shot.'); return; }
        _obsApply({current_scene: d.current_scene});
      });
  }

  // ── YouTube go-live ─────────────────────────────────────────────────────────
  const OBS_YT_LINK_URL   = "/ttrpg/obs/api/yt/link";
  const OBS_YT_POLL_URL   = "/ttrpg/obs/api/yt/link/poll";
  const OBS_YT_UNLINK_URL = "/ttrpg/obs/api/yt/unlink";
  const OBS_YT_GOLIVE_URL = "/ttrpg/obs/api/yt/golive";

  function _ytMsg(id, html) {
    const el = document.getElementById(id);
    if (el) el.innerHTML = html;
  }

  let _ytPollTimer = null;

  // Device flow: show the code, then poll until Google says the DM typed it.
  // The PAGE drives the polling, so closing the tab simply stops asking.
  function obsYtLink(btn) {
    btn.disabled = true;
    _obsPost(OBS_YT_LINK_URL, {}).then(({ok, d}) => {
      btn.disabled = false;
      if (!ok || !d.ok) { _ytMsg('obs-yt-link-msg', d.error || 'Could not start linking.'); return; }
      _ytMsg('obs-yt-link-msg',
             'On any device, open <a href="' + d.verification_url +
             '" target="_blank" rel="noopener">' + d.verification_url +
             '</a> and enter <b style="letter-spacing:.15em;">' + d.user_code +
             '</b> &mdash; waiting&hellip;');
      const interval = Math.max(3, d.interval || 5) * 1000;
      clearTimeout(_ytPollTimer);
      const poll = () => {
        _obsPost(OBS_YT_POLL_URL, {}).then(({ok: pok, d: pd}) => {
          if (!pok || !pd.ok) { _ytMsg('obs-yt-link-msg', pd.error || 'Linking failed.'); return; }
          if (pd.state === 'ok') {
            _ytMsg('obs-yt-link-msg', '&#10003; Linked' +
                   (pd.channel ? ' as <b>' + pd.channel + '</b>' : '') +
                   ' &mdash; reloading&hellip;');
            setTimeout(() => _obsReload(), 900);
            return;
          }
          _ytPollTimer = setTimeout(poll, interval);
        });
      };
      _ytPollTimer = setTimeout(poll, interval);
    });
  }

  function obsYtUnlink(btn) {
    if (!confirm('Unlink the YouTube account? Going live from this page will ' +
                 'stop working until it is linked again.')) return;
    btn.disabled = true;
    _obsPost(OBS_YT_UNLINK_URL, {}).then(() => _obsReload());
  }

  function obsYtGoLive(btn) {
    const orig = btn.innerHTML;
    btn.disabled = true; btn.innerHTML = 'Creating broadcast…';
    _ytMsg('obs-yt-live-msg', '');
    _obsPost(OBS_YT_GOLIVE_URL, {}).then(({ok, d}) => {
      btn.disabled = false; btn.innerHTML = orig;
      if (!ok || !d.ok) {
        _ytMsg('obs-yt-live-msg', d.error || 'Could not go live.');
        return;
      }
      _ytMsg('obs-yt-live-msg',
             '&#128308; Live &mdash; <a href="' + d.watch_url +
             '" target="_blank" rel="noopener">' + d.watch_url + '</a>' +
             (d.thumb_warning
              ? ' <span class="text-muted">(thumbnail skipped: ' +
                d.thumb_warning + ')</span>' : ''));
    });
  }

  // ── DM microphone picker ────────────────────────────────────────────────────
  // Fills the mic-label field from the browser's own device list, so the DM
  // never has to guess what the browser calls their microphone. Two hard
  // browser rules shape this: device LABELS are blank until the page has mic
  // permission (so we ask via getUserMedia and immediately stop the track),
  // and navigator.mediaDevices only exists on HTTPS or localhost — over plain
  // http on a LAN address there is nothing to enumerate.
  async function obsListMics(btn) {
    const sel = document.getElementById('obs-dm-mic-list');
    if (!(navigator.mediaDevices && navigator.mediaDevices.enumerateDevices)) {
      alert('This page can only read device names over HTTPS or when opened ' +
            'on this machine (localhost). Open ScenePlay that way and try ' +
            'again — or copy the name from the mic picker on your camera ' +
            'page, which shows the same labels.');
      return;
    }
    const orig = btn.innerHTML;
    btn.disabled = true; btn.innerHTML = 'Asking…';
    try {
      // Permission unlock: labels come back empty without it. The track is
      // stopped at once — nothing records, the browser just trusts us more.
      try {
        const s = await navigator.mediaDevices.getUserMedia({audio: true});
        s.getTracks().forEach(t => t.stop());
      } catch (e) { /* denied — labels may still exist if granted before */ }
      const mics = (await navigator.mediaDevices.enumerateDevices())
        .filter(d => d.kind === 'audioinput' && (d.label || '').trim());
      if (!mics.length) {
        alert('The browser would not share its device names — allow ' +
              'microphone access for this site and try again.');
        return;
      }
      sel.innerHTML = '';
      const ph = document.createElement('option');
      ph.value = ''; ph.textContent = '— pick your microphone —';
      sel.appendChild(ph);
      mics.forEach(d => {
        const o = document.createElement('option');
        o.value = d.label; o.textContent = d.label;
        sel.appendChild(o);
      });
      sel.hidden = false;
    } finally {
      btn.disabled = false; btn.innerHTML = orig;
    }
  }

  function obsPickMic(sel) {
    if (!sel.value) return;
    // The monitor IS what this field exists to avoid — warn, don't forbid:
    // on a machine deliberately streaming its own output it can be right.
    if (/^monitor of/i.test(sel.value) &&
        !confirm('"' + sel.value + '" is the speakers’ loopback, not a ' +
                 'microphone — it would carry the music and every player’s ' +
                 'voice. Use it anyway?')) {
      sel.value = '';
      return;
    }
    const inp = document.getElementById('obs-dm-mic');
    inp.value = sel.value;
    sel.hidden = true;
    obsAutoSave();          // set from JS, so the field never fires 'change'
  }

  // ── saved panel notes ───────────────────────────────────────────────────────
  const OBS_NOTE_SAVE_URL   = "/ttrpg/obs/api/panel-notes";
  const OBS_NOTE_SHOW_URL   = "/ttrpg/obs/api/panel-notes/show";
  const OBS_NOTE_DELETE_URL = "/ttrpg/obs/api/panel-notes/delete";

  function _obsNoteSel() { return document.getElementById('obs-note-lib'); }
  function _obsNoteBox() {
    return document.querySelector('textarea[name="obs_info_text"]');
  }

  // Every notes endpoint answers with the refreshed library, so the dropdown
  // is rebuilt from the server's truth rather than patched locally.
  function _obsNoteRebuild(notes, keepId) {
    const sel = _obsNoteSel();
    if (!sel || !notes) return;
    sel.innerHTML = '';
    const ph = document.createElement('option');
    ph.value = ''; ph.textContent = '— saved notes —';
    sel.appendChild(ph);
    notes.forEach(n => {
      const o = document.createElement('option');
      o.value = n.id;
      o.textContent = n.title + (n.shared ? ' (every session)' : '');
      o.dataset.shared = n.shared ? '1' : '';
      sel.appendChild(o);
    });
    if (keepId) sel.value = String(keepId);
  }

  function obsNoteSelect(sel) {
    // Mirror the note's scope into the checkbox so "save under the same name"
    // keeps it where it lives.
    const opt = sel.options[sel.selectedIndex];
    const shared = document.getElementById('obs-note-shared');
    if (shared && opt) shared.checked = !!(opt.dataset && opt.dataset.shared);
  }

  function obsNoteShow() {
    const sel = _obsNoteSel();
    if (!sel || !sel.value) { alert('Pick a saved note first.'); return; }
    _obsPost(OBS_NOTE_SHOW_URL, {note_id: +sel.value}).then(({ok, d}) => {
      if (!ok || !d.ok) { alert(d.error || 'Could not show the note.'); return; }
      const ta = _obsNoteBox();
      if (ta) ta.value = d.body;      // the box mirrors what is now on stream
      _obsNoteRebuild(d.notes, sel.value);
      _obsSavedPill();
    });
  }

  function obsNoteSave() {
    const ta = _obsNoteBox();
    const sel = _obsNoteSel();
    const opt = sel && sel.value ? sel.options[sel.selectedIndex] : null;
    const current = opt ? opt.textContent.replace(/ \(every session\)$/, '') : '';
    const title = (prompt('Name this note', current) || '').trim();
    if (!title) return;
    const shared = !!document.getElementById('obs-note-shared')?.checked;
    // The same name as the selected note means UPDATE it; a new name is a new
    // note, so a tweaked copy never silently eats the original.
    const body = {title, body: ta ? ta.value : '', shared};
    if (opt && title === current) body.note_id = +sel.value;
    _obsPost(OBS_NOTE_SAVE_URL, body).then(({ok, d}) => {
      if (!ok || !d.ok) { alert(d.error || 'Could not save the note.'); return; }
      _obsNoteRebuild(d.notes, d.note_id);
      _obsSavedPill();
    });
  }

  function obsNoteDelete() {
    const sel = _obsNoteSel();
    if (!sel || !sel.value) { alert('Pick a saved note first.'); return; }
    const opt = sel.options[sel.selectedIndex];
    if (!confirm('Delete "' + opt.textContent + '" from the saved notes?')) return;
    _obsPost(OBS_NOTE_DELETE_URL, {note_id: +sel.value}).then(({ok, d}) => {
      if (!ok || !d.ok) { alert(d.error || 'Could not delete the note.'); return; }
      _obsNoteRebuild(d.notes, null);
    });
  }

  // The address ScenePlay worked out for this machine. Preferred over reading
  // location.origin in the browser, because a DM browsing on localhost would
  // otherwise fill in an address only this machine can resolve — the exact
  // mistake that renders every OBS source blank.
  const OBS_SUGGESTED_BASE = G.CARD_BASE_SUGGESTED;

  function obsUseThisMachine(btn) {
    const inp = document.getElementById('obs-card-base');
    if (!inp) return;
    inp.value = OBS_SUGGESTED_BASE;
    inp.focus();
    const orig = btn.textContent;
    btn.textContent = '\u2713 Filled';
    obsAutoSave();   // the field never fires 'change' when set from JS
    setTimeout(() => { btn.textContent = orig; }, 2500);
  }

  // Which path Automatic would choose right now, decided server-side: whether
  // OBS can read this machine's audio devices is not something the page can know.
  const OBS_MUSIC_AUTO = G.MUSIC_AUTO;

  // ── auto-save ───────────────────────────────────────────────────────────────
  // Every settings field saves itself on change — there is no Save button to
  // hunt for. 'change' rather than 'input' on purpose: text fields commit on
  // blur, so typing a host address does not fire a reconnect per keystroke.
  // Posts the WHOLE form each time (FormData collects the form= -bound fields
  // scattered across the cards too), which the server already parses as one.
  let _obsSaveTimer = null;
  let _obsSaveAgain = false;
  let _obsSaving = false;

  function obsAutoSave() {
    clearTimeout(_obsSaveTimer);
    _obsSaveTimer = setTimeout(() => {
      if (_obsSaving) { _obsSaveAgain = true; return; }   // serialise saves
      const form = document.getElementById('obs-cfg-form');
      if (!form) return;
      _obsSaving = true;
      fetch(form.action, {method: 'POST', body: new FormData(form),
                          headers: {'X-Requested-With': 'fetch'}})
        .then(r => (r.ok ? r.json() : Promise.reject(r.status)))
        .then(d => {
          _obsSavedPill();
          // Show what was actually stored when the server tidied the room name
          // (punctuation stripped, length capped) — no reload will reveal it.
          const roomEl = document.getElementById('obs-vdo-room');
          if (roomEl && d.room !== undefined && roomEl !== document.activeElement
              && roomEl.value.trim() !== d.room) {
            roomEl.value = d.room;
          }
          if (d.reconnecting) {
            const note = document.getElementById('obs-output-note');
            if (note) note.textContent = 'Reconnecting to OBS…';
          }
        })
        .catch(() => {
          _obsShowBuildReport({error: 'A setting failed to save — check the ' +
                                      'connection and change it again.'});
        })
        .finally(() => {
          _obsSaving = false;
          if (_obsSaveAgain) { _obsSaveAgain = false; obsAutoSave(); }
        });
    }, 400);
  }

  ctx.on(document, 'change', (e) => {
    const el = e.target;
    if (!el || !el.name) return;
    // Only fields that belong to the settings form — file inputs and the
    // upload forms keep their own submit.
    const form = el.form || (el.getAttribute && el.getAttribute('form')
                             ? document.getElementById(el.getAttribute('form'))
                             : null);
    if (!form || form.id !== 'obs-cfg-form') return;
    if (el.type === 'file') return;
    obsAutoSave();
  });

  // Grey out the path that is NOT in use. Both blocks used to sit there live at
  // once, so it was possible to fill in feed settings while the device path was
  // running and see nothing to say those fields did nothing.
  function obsPaintMusicPath() {
    const sel = document.getElementById('obs-music-transport');
    if (!sel) return;
    const chosen = sel.value;
    const active = chosen === 'auto' ? OBS_MUSIC_AUTO : chosen;
    [['obs-music-device-block', 'device'],
     ['obs-music-feed-block', 'feed']].forEach(([id, owns]) => {
      const el = document.getElementById(id);
      if (!el) return;
      const on = (active === owns);
      el.style.opacity = on ? '1' : '.4';
      // Not just faded: a disabled field cannot be typed into OR submitted, so
      // an unused path can never quietly contribute a value.
      el.querySelectorAll('input, select, textarea').forEach(f => {
        f.disabled = !on;
      });
      el.querySelectorAll('a').forEach(a => {
        a.style.pointerEvents = on ? '' : 'none';
        a.setAttribute('aria-disabled', on ? 'false' : 'true');
      });
    });
    const now = document.getElementById('obs-music-now');
    if (now) now.textContent = active === 'off' ? 'off' : active;
    const forced = document.getElementById('obs-music-forced');
    if (forced) forced.style.display = (chosen === 'auto') ? 'none' : '';
  }
  obsPaintMusicPath();

  const OBS_MUTE_URL = "/ttrpg/obs/api/mute";
  const OBS_SCENEAUDIO_URL = "/ttrpg/obs/api/scene-audio";

  function _obsPaintMuteBtn(btn, muted) {
    btn.dataset.muted = muted ? '1' : '0';
    btn.innerHTML = muted ? '&#128263;' : '&#128266;';
    btn.classList.toggle('btn-danger', muted);
    btn.classList.toggle('btn-outline-secondary', !muted);
    btn.title = muted ? 'Muted on the stream — click to unmute'
                      : 'Mute this voice on the stream';
  }

  function obsMuteChar(btn) {
    const row = btn.closest('.obs-row');
    const cid = row && parseInt(row.dataset.characterId, 10);
    if (cid === undefined || cid === null || isNaN(cid)) return;
    const want = btn.dataset.muted !== '1';
    btn.disabled = true;
    _obsPost(OBS_MUTE_URL, {character_id: cid, muted: want})
      .then(({ok, d}) => {
        btn.disabled = false;
        if (!ok || !d.ok) {
          _obsShowBuildReport({error: (d && d.error) || 'Could not change the mute.'});
          return;
        }
        _obsPaintMuteBtn(btn, want);
        _obsSavedPill();
      });
  }

  // Scanned-server picker: fills the host field (and snaps the port back to
  // obs-websocket's 4455 — a scanned entry IS a 4455 responder). Nothing is
  // saved here; the DM still clicks Save Connection Settings.
  function obsPickHost(sel) {
    if (!sel.value) return;
    document.getElementById('obs-host-input').value = sel.value;
    document.getElementById('obs-port-input').value = '4455';
    obsAutoSave();   // JS-set fields fire no 'change' — save explicitly
  }

  // Hand-typing a different host un-picks the dropdown, so it never claims a
  // selection the field below contradicts.
  (function () {
    const host = document.getElementById('obs-host-input');
    const pick = document.getElementById('obs-host-pick');
    if (host && pick) {
      host.addEventListener('input', () => {
        if (pick.value && pick.value !== host.value.trim()) pick.value = '';
      });
    }
  })();

  function obsMuteAll(scope, muted) {
    _obsPost(OBS_MUTE_URL, {all: scope, muted})
      .then(({ok, d}) => {
        if (!ok || !d.ok) {
          _obsShowBuildReport({error: (d && d.error) || 'Could not change the mutes.'});
          return;
        }
        // Repaint every row from the server's answer — the DM's own row is
        // deliberately not part of "all", so it must keep its current state.
        const ids = new Set(d.muted_ids || []);
        document.querySelectorAll('.obs-row').forEach(row => {
          const btn = row.querySelector('.obs-mute-btn');
          if (btn) _obsPaintMuteBtn(btn, ids.has(parseInt(row.dataset.characterId, 10)));
        });
        _obsSavedPill();
      });
  }

  const OBS_NEWROOM_URL = "/ttrpg/obs/api/room/new";

  function obsNewRoom(btn) {
    const cur = document.getElementById('obs-vdo-room').value.trim();
    // Replacing a live room strands anyone already in the old one, so make the
    // DM say yes to that specifically — creating the FIRST room is harmless.
    if (cur && !confirm('Replace the room "' + cur + '"?\n\nEveryone in the ' +
                        'old room will be left behind until they reopen their ' +
                        'camera link.')) return;
    const orig = btn.textContent;
    btn.disabled = true; btn.textContent = 'Creating…';
    _obsPost(OBS_NEWROOM_URL, {})
      .then(({ok, d}) => {
        btn.disabled = false; btn.textContent = orig;
        if (!ok || !d.ok) {
          _obsShowBuildReport({error: (d && d.error) || 'Could not create a room.'});
          return;
        }
        document.getElementById('obs-vdo-room').value = d.room;
        // Reload so the join link and the explanatory note match the new room
        // rather than describing the state it was in a moment ago.
        _obsReload();
      });
  }

  const OBS_REPORT_KEY = 'obsBuildReport';

  function _obsShowBuildReport(rep) {
    const box = document.getElementById('obs-build-report');
    if (!box || !rep) return;
    const esc = s => String(s).replace(/[&<>]/g,
      c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;'}[c]));
    const warn = rep.warnings || [];
    const contents = rep.contents || {};
    const scenes = Object.keys(contents);
    if (!rep.error && !warn.length && !scenes.length) { box.hidden = true; return; }

    let html = '';
    if (rep.error) {
      html += '<div class="alert alert-danger py-2 px-3 mb-2">' +
              esc(rep.error) + '</div>';
    }
    if (warn.length) {
      html += '<div class="alert alert-warning py-2 px-3 mb-2">' +
              '<ul class="mb-0 ps-3">' +
              warn.map(w => '<li>' + esc(w) + '</li>').join('') + '</ul></div>';
    }
    if (scenes.length) {
      // Collapsed: at a glance what matters is whether anything warned. The
      // inventory is one click away for when a source is quietly missing.
      html += '<details><summary class="text-muted" style="cursor:pointer">' +
              'What OBS is holding (' + scenes.length + ' scenes)</summary>' +
              '<div class="mt-2">' + scenes.map(sc =>
                '<div class="mb-1"><b>' + esc(sc) + '</b><ul class="mb-0 ps-3">' +
                (contents[sc] || []).map(s => '<li>' + esc(s) + '</li>').join('') +
                '</ul></div>').join('') + '</div></details>';
    }
    box.innerHTML = html;
    box.hidden = false;
  }

  function obsBuildParty(btn) {
    const orig = btn.innerHTML;
    btn.disabled = true; btn.textContent = 'Building…';
    _obsPost(OBS_BUILD_URL, {})
      .then(({ok, d}) => {
        btn.disabled = false; btn.innerHTML = orig;
        if (!ok || !d.ok) {
          _obsShowBuildReport({error: (d && d.error) ||
                                      'Could not build the party scene.'});
          return;
        }
        // What OBS actually ended up holding. "Built successfully" while a
        // source is quietly missing is the failure mode this reports. It rides
        // through the reload below in sessionStorage so it can live on the page
        // instead of in a modal that has to be dismissed first.
        try {
          sessionStorage.setItem(OBS_REPORT_KEY, JSON.stringify(
            {warnings: d.warnings || [], contents: d.contents || {}}));
        } catch (e) { /* private mode: the reload simply shows nothing */ }
        _obsReload();
      })
      .catch(() => { btn.disabled = false; btn.innerHTML = orig; });
  }

  // Pick the report back up on the far side of the reload, once.
  (function () {
    let raw = null;
    try {
      raw = sessionStorage.getItem(OBS_REPORT_KEY);
      sessionStorage.removeItem(OBS_REPORT_KEY);
    } catch (e) { return; }
    if (raw) {
      try { _obsShowBuildReport(JSON.parse(raw)); } catch (e) { /* ignore */ }
    }
  })();

  // Saving posts and redirects, which lands back at the top of the page — a long
  // scroll away from the setting just changed. Stash the position on the way out
  // and put it back on the way in.

  function _obsSavedPill() {
    // The "OBS settings saved" flash renders at the top of the page, which is
    // precisely where the DM is no longer looking once the position is kept.
    const pill = document.createElement('div');
    pill.textContent = '✓ Settings saved';
    pill.setAttribute('role', 'status');
    pill.id = 'obs-saved-pill';
    pill.style.cssText =
      'position:fixed;left:50%;transform:translateX(-50%);bottom:1.5rem;' +
      'z-index:1080;padding:.4rem .9rem;border-radius:999px;' +
      'background:var(--ttrpg-accent);color:var(--sp-on-accent);' +
      'font-size:.85rem;box-shadow:0 2px 10px rgba(0,0,0,.35);' +
      'transition:opacity .4s;';
    document.body.appendChild(pill);
    setTimeout(function () { pill.style.opacity = '0'; }, 1800);
    setTimeout(function () { pill.remove(); }, 2400);
  }


  function obsSetMapMode(mode) {
    _obsPost(OBS_MAPMODE_URL, {mode})
      .then(({ok, d}) => {
        if (!ok || !d.ok) { alert(d.error || 'Could not switch the map view.'); return; }
        _paintMapMode(d.mode);
      });
  }

  function obsReloadMap(btn) {
    const orig = btn.innerHTML;
    btn.disabled = true; btn.innerHTML = 'Reloading\u2026';
    _obsPost(OBS_MAPRELOAD_URL, {})
      .then(({ok, d}) => {
        btn.disabled = false;
        if (!ok || !d.ok) { btn.innerHTML = orig; alert(d.error || 'Could not reload the map source.'); return; }
        btn.innerHTML = '\u2713 Reloaded';
        setTimeout(() => { btn.innerHTML = orig; }, 2000);
      })
      .catch(() => { btn.disabled = false; btn.innerHTML = orig; });
  }

  // A source that cached a blank page keeps showing it: the settings and the
  // transform look perfect and nothing renders. This is the cure for that.
  function obsReloadAll(btn) {
    const orig = btn.innerHTML;
    btn.disabled = true; btn.innerHTML = 'Reloading\u2026';
    _obsPost(OBS_RELOADALL_URL, {})
      .then(({ok, d}) => {
        btn.disabled = false; btn.innerHTML = orig;
        if (!ok || !d.ok) { alert(d.error || 'Could not reload the sources.'); return; }
        const msg = ['Refreshed ' + (d.refreshed || []).length + ' source(s):']
          .concat((d.refreshed || []).map(s => '   \u2022 ' + s));
        if (d.failed && d.failed.length) {
          msg.push('', 'Failed:');
          (d.failed).forEach(f => msg.push('   \u2022 ' + f));
        }
        alert(msg.join('\n'));
      })
      .catch(() => { btn.disabled = false; btn.innerHTML = orig; });
  }

  function _paintMapMode(mode) {
    [['obs-mode-auto', 'auto'], ['obs-mode-2d', '2d'],
     ['obs-mode-3d', '3d']].forEach(([id, m]) => {
      const b = document.getElementById(id);
      if (!b) return;
      const on = m === mode;
      b.style.background = on ? 'var(--ttrpg-accent)' : 'var(--ttrpg-surface)';
      b.style.color = on ? 'var(--sp-on-accent)' : 'var(--ttrpg-text)';
      b.style.border = on ? 'none' : '1px solid var(--sp-border)';
    });
  }
  _paintMapMode(G.MAP_MODE);

  function obsCardOverride(chk) {
    const row = chk.closest('.obs-row');
    _obsPost(OBS_CARDOVR_URL, {character_id: row.dataset.characterId,
                               show_card: chk.checked})
      .then(({ok, d}) => {
        if (!ok || !d.ok) { alert(d.error || 'Could not switch that tile.'); chk.checked = !chk.checked; }
        else obsPoll();
      });
  }

  function obsOnStream(chk) {
    const row = chk.closest('.obs-row');
    chk.disabled = true;
    _obsPost(OBS_ONSTREAM_URL, {character_id: row.dataset.characterId,
                                on_stream: chk.checked})
      .then(({ok, d}) => {
        chk.disabled = false;
        if (!ok || !d.ok) {
          alert(d.error || 'Could not change that player.');
          chk.checked = !chk.checked;
          return;
        }
        // The running order renumbers around the gap, so reload rather than
        // leave the positions on screen lying about which key features whom.
        _obsReload();
      })
      .catch(() => { chk.disabled = false; chk.checked = !chk.checked; });
  }

  function obsReorder(characterId, delta) {
    _obsPost(OBS_REORDER_URL, {character_id: characterId, delta})
      .then(({ok, d}) => { if (ok && d.ok) _obsReload(); });
  }

  function obsSceneAudio(sel) {
    const row = sel.closest('.obs-scene-row');
    const note = row.querySelector('.obs-scene-note');
    _obsPost(OBS_SCENEAUDIO_URL, {scene_id: row.dataset.sceneId,
                                  policy: sel.value})
      .then(({ok, d}) => {
        if (!ok || !d.ok) {
          _obsShowBuildReport({error: (d && d.error) || 'Could not save.'});
          return;
        }
        if (note) {
          note.innerHTML = '<span style="color:#3fa14a;">✓ saved</span>';
          setTimeout(() => { note.textContent = ''; }, 2500);
        }
      });
  }

  function obsSaveSceneLink(inp) {
    const row = inp.closest('.obs-scene-row');
    const note = row.querySelector('.obs-scene-note');
    _obsPost(OBS_MAPSCENE_URL, {scene_id: row.dataset.sceneId, scene_name: inp.value.trim()})
      .then(({ok, d}) => {
        if (!ok || !d.ok) { alert(d.error || 'Could not save.'); return; }
        // Say so: a silent save on a field that used to do nothing is exactly
        // what made this look broken.
        if (note) {
          note.innerHTML = d.scene_name
            ? '<span style="color:#3fa14a;">\u2713 linked</span>'
            : '<span class="text-muted">cleared</span>';
          setTimeout(() => { note.textContent = ''; }, 2500);
        }
      });
  }

  // Number keys jump to a player; arrows step; 0 or G returns to the group.
  // Ignored while typing so the scene dropdowns stay usable.
  ctx.on(document, 'keydown', e => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'SELECT' ||
              t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    if (e.key >= '1' && e.key <= '9') { e.preventDefault(); obsJump(parseInt(e.key)); }
    else if (e.key === '0' || e.key.toLowerCase() === 'g') { e.preventDefault(); obsGroup(); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); obsStep(1); }
    else if (e.key === 'ArrowLeft')  { e.preventDefault(); obsStep(-1); }
  });

  function obsRefreshScenes(btn) {
    btn.disabled = true;
    _obsPost(OBS_REFRESH_URL, {})
      .then(({ok, d}) => {
        btn.disabled = false;
        if (!ok || !d.ok) { alert(d.error || 'Could not read scenes.'); return; }
        _obsReload();   // rebuild the dropdowns from the fresh list
      })
      .catch(() => { btn.disabled = false; });
  }

  // Optimistic click, then the 3 s poll corrects — same shape as the battle
  // map's scene buttons.
  function _obsApply(s) {
    if (s.current_scene !== undefined) {
      const el = document.getElementById('obs-current-scene');
      if (el) el.textContent = s.current_scene || '—';
      document.querySelectorAll('.obs-scene-btn').forEach(b => {
        const on = b.dataset.scene === s.current_scene;
        b.style.background = on ? 'var(--ttrpg-accent)' : 'var(--ttrpg-surface)';
        b.style.color = on ? 'var(--sp-on-accent)' : 'var(--ttrpg-text)';
        b.style.borderColor = on ? 'var(--ttrpg-accent)' : 'var(--sp-border)';
      });
    }
    if (s.state !== undefined) {
      const badge = document.getElementById('obs-state-badge');
      const label = {connected: 'Connected', connecting: 'Connecting…',
                     identifying: 'Connecting…', reconnecting: 'Reconnecting…',
                     auth_failed: 'Auth failed', unsupported: 'Unsupported',
                     disabled: 'Disabled'}[s.state] || s.state;
      const cls = s.state === 'connected' ? 'bg-success'
                : (s.state === 'auth_failed' || s.state === 'unsupported') ? 'bg-danger'
                : s.state === 'disabled' ? 'bg-secondary' : 'bg-warning text-dark';
      badge.className = 'badge ms-1 ' + cls;
      badge.textContent = label;
    }
    if (s.recording !== undefined) {
      document.getElementById('obs-rec-pill').style.display = s.recording ? 'inline-block' : 'none';
    }
    if (s.streaming !== undefined) {
      document.getElementById('obs-live-pill').style.display = s.streaming ? 'inline-block' : 'none';
    }
    _obsPaintOutputs(s);
  }

  // The buttons say what OBS is doing, never what this page last asked for —
  // so starting or stopping inside OBS itself is reflected here within a poll.
  function _obsPaintOutputs(s) {
    const live = s.state === 'connected';
    [['obs-record-btn', s.recording, '&#9679; Start recording', '&#9632; Stop recording',
      'btn-outline-danger', 'btn-danger'],
     ['obs-stream-btn', s.streaming, '&#9654; Start streaming', '&#9632; Stop streaming',
      'btn-outline-primary', 'btn-primary']
    ].forEach(([id, on, offLabel, onLabel, offCls, onCls]) => {
      const b = document.getElementById(id);
      if (!b || on === undefined) return;
      if (b.dataset.busy === '1') return;         // mid-request, leave it alone
      b.disabled = !live;
      b.innerHTML = on ? onLabel : offLabel;
      b.classList.remove(offCls, onCls);
      b.classList.add(on ? onCls : offCls);
      b.dataset.on = on ? '1' : '0';
    });
    const note = document.getElementById('obs-output-note');
    if (note) {
      note.textContent = live ? (s.recording ? '' : 'Not recording.')
                              : 'Connect to OBS to record or stream.';
    }
  }

  function obsOutput(kind, btn) {
    const on = btn.dataset.on === '1';
    // Confirm anything that ends a take or touches the public broadcast.
    // Starting a recording is the one action left frictionless — it is the one
    // you never want to hesitate over.
    const ask = on
      ? (kind === 'record' ? 'Stop recording? The take ends here.'
                           : 'Stop streaming? This ends the broadcast for everyone watching.')
      : (kind === 'stream' ? 'Start streaming? This goes live publicly.' : null);
    if (ask && !confirm(ask)) return;

    const orig = btn.innerHTML;
    btn.dataset.busy = '1';
    btn.disabled = true;
    btn.textContent = on ? 'Stopping…' : 'Starting…';
    _obsPost(OBS_OUTPUT_URL.replace('__kind__', kind), {on: !on})
      .then(({ok, d}) => {
        btn.dataset.busy = '0';
        btn.disabled = false;
        if (!ok || !d.ok) {
          btn.innerHTML = orig;
          _obsShowBuildReport({error: (d && d.error) ||
                                      ('Could not ' + (on ? 'stop ' : 'start ') + kind + '.')});
          return;
        }
        _obsPaintOutputs(d);       // reflect the state OBS actually reported
      })
      .catch(() => {
        btn.dataset.busy = '0'; btn.disabled = false; btn.innerHTML = orig;
      });
  }

  function obsPoll() {
    if (_dead) return;
    fetch(OBS_STATE_URL).then(r => r.json()).then(_obsApply).catch(() => {});
  }
  obsPoll();
  ctx.subscribe('obs', () => obsPoll(), { fallback: { every: 3000, fetch: async () => null } });
  ctx.every(15000, obsPoll);   // belt and braces: rows/presence have no event of their own

  // "Choose existing" for a show-art slot: submit the slot's own upload form
  // with a shared reference instead of a file (routes/obs.py upload_image).
  function obsReuseArt(form, kinds) {
    if (!form) return;
    spPickAsset({ kinds: kinds, onPick: it => {
      let ref = form.querySelector('input[name=ref]');
      if (!ref) { ref = document.createElement('input'); ref.type = 'hidden'; ref.name = 'ref'; form.appendChild(ref); }
      ref.value = spAssetRef(it, 'obs');
      _obsSubmitForm(form);
    }});
  }

  const NAMES = ["_obsPost", "obsSwitchScene", "obsStep", "obsJump", "obsGroup", "_ytMsg", "obsYtLink", "obsYtUnlink", "obsYtGoLive", "obsListMics", "obsPickMic", "_obsNoteSel", "_obsNoteBox", "_obsNoteRebuild", "obsNoteSelect", "obsNoteShow", "obsNoteSave", "obsNoteDelete", "obsUseThisMachine", "obsAutoSave", "obsPaintMusicPath", "_obsPaintMuteBtn", "obsMuteChar", "obsPickHost", "obsMuteAll", "obsNewRoom", "_obsShowBuildReport", "obsBuildParty", "_obsSavedPill", "obsSetMapMode", "obsReloadMap", "obsReloadAll", "_paintMapMode", "obsCardOverride", "obsOnStream", "obsReorder", "obsSceneAudio", "obsSaveSceneLink", "obsRefreshScenes", "_obsApply", "_obsPaintOutputs", "obsOutput", "obsPoll", "obsReuseArt", "_obsReload", "_obsSubmitForm"];
  exposeGlobals({ _obsPost, obsSwitchScene, obsStep, obsJump, obsGroup, _ytMsg, obsYtLink, obsYtUnlink, obsYtGoLive, obsListMics, obsPickMic, _obsNoteSel, _obsNoteBox, _obsNoteRebuild, obsNoteSelect, obsNoteShow, obsNoteSave, obsNoteDelete, obsUseThisMachine, obsAutoSave, obsPaintMusicPath, _obsPaintMuteBtn, obsMuteChar, obsPickHost, obsMuteAll, obsNewRoom, _obsShowBuildReport, obsBuildParty, _obsSavedPill, obsSetMapMode, obsReloadMap, obsReloadAll, _paintMapMode, obsCardOverride, obsOnStream, obsReorder, obsSceneAudio, obsSaveSceneLink, obsRefreshScenes, _obsApply, _obsPaintOutputs, obsOutput, obsPoll, obsReuseArt, _obsReload, _obsSubmitForm });
  return () => {
    _dead = true;
    try { clearTimeout(_ytPollTimer); } catch (e) {}
    try { clearTimeout(_obsSaveTimer); } catch (e) {}
    document.querySelectorAll('#obs-saved-pill').forEach(el => el.remove());
    unexposeGlobals(NAMES);
  };
}
